<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue';import {createPmsEcho} from './realtime';import {pmsApi} from './api';const props=defineProps<{csrf?:string}>();const data=ref<any>(null),opened=ref(false),error=ref('');let echo:any;async function load(){try{data.value=await pmsApi('notifications');}catch(e){error.value=(e as Error).message;}}async function read(){await pmsApi('notifications/read-all',props.csrf,'POST',{});await load();}
function outside(e:MouseEvent){if(!(e.target as HTMLElement).closest('.pms-notifications'))opened.value=false;}
onMounted(async()=>{document.addEventListener('click',outside);await load();if(!data.value?.user_id)return;echo=await createPmsEcho(props.csrf||'');if(!echo)return;const channel=echo.private('pms.user.'+data.value.user_id).notification(()=>void load());for(const event of ['TaskNotification','TaskApprovalNotification','ProjectAssignedNotification','TaskReminderNotification'])channel.listen('.'+event,()=>void load());});onUnmounted(()=>{document.removeEventListener('click',outside);echo?.disconnect();});
</script><template><div class="pms-notifications" style="position:relative"><button class="button" aria-label="Notifications" :aria-expanded="opened" @click="opened=!opened"><i aria-hidden="true" class="ti ti-bell"></i><span v-if="data?.unread">{{data.unread}}</span></button><div v-if="opened" class="card p-3 pms-notification-dropdown" style="position:absolute;right:0;top:100%;width:350px;max-height:450px;overflow:auto;z-index:100"><div class="admin-section-heading"><strong>Notifications</strong><button class="button" @click="read">Mark all read</button></div><p v-if="error">{{error}}</p><a v-for="n in data?.items" :key="n.id" class="pms-deadline-row" :href="'/pms/api/notifications/'+n.id+'/open'"><strong>{{n.data.subject||n.data.message||'PMS update'}}</strong><small>{{n.data.message}} &middot; {{new Date(n.created_at).toLocaleString()}}</small></a><p v-if="!data?.items.length" class="muted">No notifications yet.</p></div></div></template>